 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { color, uv, texture, add, sub, mul, rand, vec2, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, Mesh, DoubleSide } = THREE;

  const group = new Group();
  const cleanupFns = [];
  const timelines = [];

  const region = config.atlasRegion ?? { x: 0, y: 0, width: 512, height: 320 };
  const aspect = region.width / region.height;

  const cardWidth = 1.28;
  const cardHeight = cardWidth / aspect;

  const geometry = new PlaneGeometry(cardWidth, cardHeight);
  const material = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: false,
  });

  const visualColors = config.intent?.visualSpec?.colors ?? config.visual?.colors ?? {};
  material.colorNode = color(visualColors.surface ?? '#0b0b10');

  const plane = new Mesh(geometry, material);
  group.add(plane);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (!tex || !plane.parent) return;

      tex.colorSpace = THREE.SRGBColorSpace;
      tex.minFilter = THREE.LinearFilter;
      tex.magFilter = THREE.LinearFilter;
      tex.generateMipmaps = false;
      tex.needsUpdate = true;

      const texNode = texture(tex, uv());
      const noise = sub(mul(rand(mul(uv(), vec2(1024.0, 1024.0))), 0.03), 0.015);
      material.colorNode = add(texNode, vec3(noise));
      material.needsUpdate = true;

      cleanupFns.push(() => tex.dispose());
    }).catch(() => {});
  }

  for (const p of config.cinematicPrimitives ?? []) {
    if (typeof ctx.primitives?.[p.name] === 'function') {
      const result = ctx.primitives[p.name](group, p.params ?? {});
      if (result?.timeline) timelines.push(result.timeline);
      if (typeof result?.cleanup === 'function') cleanupFns.push(result.cleanup);
    }
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timelines.forEach((tl) => {
      if (tl && typeof tl.kill === 'function') tl.kill();
    });
    cleanupFns.forEach((fn) => {
      if (typeof fn === 'function') fn();
    });
    geometry.dispose();
    material.dispose();
    if (group.parent) group.parent.remove(group);
  };

  return group;
}
